const res = await fetch('/api/deliverability/check', {
  method: 'POST',
  headers: { 'content-type': 'application/json', authorization: `Bearer ${jwt}` },
  body: JSON.stringify({ tenant_id: tenantId, channel: 'email', addresses: ['a@x.com', 'b@y.com'] }),
});
const { data } = await res.json();
const sendable = data.results.filter((r) => !r.suppressed).map((r) => r.address);

import { suppressionService } from '@projexlight/sdk-deliverability';

const suppression = await suppressionService.suppress({
  tenantId,
  channel: 'email',
  address: 'user@example.com',
  reason: 'dnc',
  source: 'support-ticket',
});
const blocked = await suppressionService.isSuppressed({ tenantId, channel: 'email', address: 'user@example.com' });

const res = await fetch('/api/deliverability/optout/redeem', {
  method: 'POST',
  headers: { 'content-type': 'application/json', authorization: `Bearer ${jwt}` },
  body: JSON.stringify({ token: rawToken, feedback: 'too many emails' }),
});
if (res.status === 410) {
  // token unknown, already used, or expired — show an idempotent 'already unsubscribed' page
} else {
  const { data } = await res.json(); // { redeemed: true }
}

// Provider POSTs to /api/deliverability/webhooks/sendgrid?tenant_id=<uuid>
// with an HMAC in x-webhook-signature. The route HMAC-verifies against the
// tenant's stored webhook_secret, then processes the payload:
import { webhookService } from '@projexlight/sdk-deliverability';

const { verified, enforced } = await webhookService.verifyWebhookSignature(tenantId, 'sendgrid', rawBody, signature);
if (enforced && !verified) throw new Error('InvalidSignature');
const result = await webhookService.processBounceWebhook({ tenantId, provider: 'sendgrid', payload, signatureVerified: verified });
